#!/usr/bin/env node
// Concatenates the CSS/JS modules script.js loads at runtime into two
// static bundle files (bundle.css, bundle.js), in the exact same order.
//
// Why this exists: the site's rendering pipeline is ~24 small JS files and
// ~23 small CSS files, each loaded as its own <link>/<script> so every
// numbered feedback-content-vN file can be edited independently. That's
// great for making small, isolated changes, but under HTTP/1.1 (which is
// what a plain `python -m http.server`-style static host serves, and
// which many CDN edges still negotiate down to under certain conditions)
// the browser caps concurrent requests per origin at ~6, so 47 small
// files becomes several serialized waves of requests before the boot gate
// can lift — that's the dominant cost, not bandwidth or script execution
// time (confirmed: same boot sequence takes ~0.6s with no artificial
// network latency, and ~8s with 40ms latency + 47 requests).
//
// This script is the fix for request COUNT without touching request
// CONTENT: each JS file is already a self-contained `(() => { ... })();`
// IIFE with no shared top-level bindings and no use of
// document.currentScript, so concatenating them in the same order they'd
// otherwise load in is semantically identical — same code, same order,
// just two HTTP requests instead of forty-seven.
//
// IMPORTANT: run this again after editing ANY file listed in script.js's
// `stylesheets`/`scripts` arrays — this script reads those arrays as its
// manifest, so nothing needs to be duplicated or kept in sync by hand,
// but the generated bundle.css/bundle.js do need regenerating or they'll
// silently keep serving the pre-edit versions. See CLAUDE.md.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const scriptJsPath = path.join(root, 'script.js');
const scriptJs = readFileSync(scriptJsPath, 'utf8');

const extractArray = (source, varName) => {
  const match = source.match(new RegExp(`${varName} = \\[([\\s\\S]*?)\\];`));
  if (!match) throw new Error(`Could not find "${varName}" array in script.js`);
  return [...match[1].matchAll(/'([^']+)'/g)].map((m) => m[1]);
};

const stylesheetFiles = extractArray(scriptJs, 'const stylesheets');
const scriptFiles = extractArray(scriptJs, 'const scripts');

const buildCss = () => {
  const parts = stylesheetFiles.map((filename) => {
    const content = readFileSync(path.join(root, filename), 'utf8');
    return `/* ==== ${filename} ==== */\n${content}`;
  });
  const header = `/* AUTO-GENERATED by scripts/build-bundle.mjs — do not edit directly.\n   Source order: ${stylesheetFiles.join(', ')}\n   Regenerate with: node scripts/build-bundle.mjs */\n\n`;
  writeFileSync(path.join(root, 'bundle.css'), header + parts.join('\n\n'));
};

const buildJs = () => {
  const parts = scriptFiles.map((filename) => {
    const content = readFileSync(path.join(root, filename), 'utf8');
    return `// ==== ${filename} ====\n${content}`;
  });
  const header = `// AUTO-GENERATED by scripts/build-bundle.mjs — do not edit directly.\n// Source order: ${scriptFiles.join(', ')}\n// Regenerate with: node scripts/build-bundle.mjs\n\n`;
  writeFileSync(path.join(root, 'bundle.js'), header + parts.join('\n\n'));
};

buildCss();
buildJs();

const cssBytes = readFileSync(path.join(root, 'bundle.css')).length;
const jsBytes = readFileSync(path.join(root, 'bundle.js')).length;
console.log(`bundle.css: ${stylesheetFiles.length} files -> ${cssBytes} bytes`);
console.log(`bundle.js:  ${scriptFiles.length} files -> ${jsBytes} bytes`);
